  ca,ma=objs[a]; cb,mb=objs[b]
  cnt=Counter((ra-rb,xa-xb) for ra,xa in ma for rb,xb in mb)
  valid=[]
  for d,n in cnt.items():
   if n<1: continue
   aset=set(ca); bset={(r+d[0],c+d[1]) for r,c in cb}
   if not aset & bset: valid.append((d,n))
  top=[x for x in valid if x[1]>=2]
  if top: print(a,b,top)

